declare(strict_types=1);require __DIR__.'/lib.php';require_once __DIR__.'/lib/user_preferences.php';require __DIR__.'/lib/charts_view.php';$db=lab_auth_pdo();$embed=!empty($_GET['embed']);$theme=lab_user_theme((string)lab_auth_current_account()['id']);$report=null;
